import{_ as i,c as t,o as a,ae as l}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"MAKING THE DISTRICT OF COLUMBIA SAFE AND BEAUTIFUL","description":"","frontmatter":{"title":"MAKING THE DISTRICT OF COLUMBIA SAFE AND BEAUTIFUL","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/making-the-district-of-columbia-safe-and-beautiful/","publishDate":"2025-03-28T09:06:12-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-28-making-the-district-of-columbia-safe-and-beautiful.md","filePath":"executive-orders/2025-03-28-making-the-district-of-columbia-safe-and-beautiful.md"}'),r={name:"executive-orders/2025-03-28-making-the-district-of-columbia-safe-and-beautiful.md"};function o(n,e,s,c,u,d){return a(),t("div",null,e[0]||(e[0]=[l('<h1 id="making-the-district-of-columbia-safe-and-beautiful" tabindex="-1">MAKING THE DISTRICT OF COLUMBIA SAFE AND BEAUTIFUL <a class="header-anchor" href="#making-the-district-of-columbia-safe-and-beautiful" aria-label="Permalink to &quot;MAKING THE DISTRICT OF COLUMBIA SAFE AND BEAUTIFUL&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/making-the-district-of-columbia-safe-and-beautiful/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/making-the-district-of-columbia-safe-and-beautiful/</a></p><p>Published: Friday, March 28, 2025</p><ul><li><p><strong>Purpose</strong>: To enhance safety, beauty, and prosperity in Washington, D.C. as the federal capital representing all Americans.</p></li><li><p><strong>Vision for D.C.</strong>:</p><ul><li>Public spaces should be clean, safe, and inspirational.</li><li>Residents and visitors should feel secure at all times.</li></ul></li><li><p><strong>Policy Objectives</strong>:</p><ul><li>Prevent crime and punish offenses.</li><li>Preserve order and protect national monuments.</li><li>Promote beautification and heritage preservation.</li></ul></li><li><p><strong>D.C. Safe and Beautiful Task Force</strong>:</p><ul><li>Established to align federal efforts with local priorities and maximize resource use.</li><li>Chaired by the Assistant to the President and Homeland Security Advisor.</li><li>Members include representatives from various federal departments and law enforcement agencies.</li></ul></li><li><p><strong>Coordination with Local Authorities</strong>:</p><ul><li>Request operational aid from local law enforcement and transit authorities.</li><li>Ensure federal participation in various safety and law enforcement tasks.</li></ul></li><li><p><strong>Key Tasks for the Task Force</strong>:</p><ul><li>Enforce federal immigration laws in the metropolitan area.</li><li>Monitor sanctuary city status for compliance.</li><li>Assist in the accreditation of D.C.&#39;s forensic crime laboratory.</li><li>Collaborate with local entities to improve police officer recruitment and capabilities.</li><li>Support expedited processing of concealed carry license requests.</li><li>Revise federal prosecutorial policies for pretrial detention.</li><li>Target fare evasion crime on public transit.</li><li>Increase federal and local law enforcement presence.</li></ul></li><li><p><strong>Beautification Program</strong>:</p><ul><li>Develop and implement a coordinated beautification plan for the city.</li><li>Restore and maintain federal monuments.</li><li>Clean graffiti in public areas.</li><li>Engage private sector participation in beautification efforts.</li></ul></li><li><p><strong>Administrative Authority</strong>:</p><ul><li>This order does not infringe upon existing legal authorities or create enforceable rights.</li></ul></li><li><p><strong>Implementation</strong>:</p><ul><li>Actions are subject to applicable laws and budgetary considerations.</li></ul></li></ul>',4)]))}const m=i(r,[["render",o]]);export{p as __pageData,m as default};
